<?php declare(strict_types=1); require dirname(__DIR__).'/autoload.php'; ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SB3 / Analyzer Upload Test</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f6f7fb}.card{border:0;box-shadow:0 .3rem 1rem rgba(0,0,0,.06)}pre{background:#111827;color:#e5e7eb;padding:14px;border-radius:10px;white-space:pre-wrap}</style></head><body><div class="container py-4"><a href="index.php" class="btn btn-sm btn-outline-secondary mb-3">← Test Merkezi</a><h1 class="h3">SB3 / Analyzer Upload Test</h1><?php $out=null;$err=null;if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_FILES['file'])){try{$a=ScratchByPHP\Sb3\Sb3Archive::open($_FILES['file']['tmp_name']);$out=['summary'=>$a->analyze()->summary(),'assets_count'=>count($a->assets()),'warnings'=>$a->analyze()->warnings()];}catch(Throwable $e){$err=$e->getMessage();}}?><div class="card"><div class="card-body"><form method="post" enctype="multipart/form-data"><input type="file" name="file" class="form-control mb-2" accept=".sb3,.json"><button class="btn btn-primary">Dosyayı Analiz Et</button></form><?php if($err):?><div class="alert alert-danger mt-3"><?=htmlspecialchars($err)?></div><?php elseif($out):?><pre class="mt-3"><?=htmlspecialchars(json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre><?php endif;?></div></div></div></body></html>